'use strict'

// @ts-expect-error - Elm module has no type definitions
import { Elm } from '../../LiaScript/src/elm/Worker.elm'

import * as WEB from '../export/web'
import { ExportFormat, HelperCommand, ElmApp, ElmWorker } from '../types'
import { Arguments } from '../parser'
import { MemoryFS } from '../fs/memory'

/**
 * Browser twin of {@link ../exporter.Exporter}.
 *
 * It is a separate class rather than a branch inside the CLI one because
 * `src/exporter.ts` imports `fs-extra` and `node-fetch` at module scope, which
 * no bundler can follow into a browser build. The parts that actually matter —
 * the Elm port protocol and the format dispatch — are small enough that
 * duplicating them costs less than making the Node entry point bundleable.
 *
 * Only the formats proven byte-identical so far are wired up; the rest throw
 * rather than silently producing nothing.
 */
export class BrowserExporter {
  /**
   * Runs one export and returns the finished archive bytes.
   *
   * Resolution is driven by the Elm `output` port, which fires once per run.
   */
  async run(argument: Arguments, markdown: string): Promise<Uint8Array> {
    const app: ElmApp = (Elm as unknown as { Worker: ElmWorker }).Worker.init({
      flags: { cmd: '' },
    })

    const fs = argument.fs as MemoryFS

    return new Promise<Uint8Array>((resolve, reject) => {
      // Relative `import` directives inside a course would need the file to be
      // in the store already; in the browser there is no directory to resolve
      // against, so report it rather than hanging on a port that never answers.
      app.ports.helper.subscribe(async ([cmd, param]) => {
        switch (cmd) {
          case HelperCommand.DEBUG:
            console.warn('DEBUG', param)
            break
          case HelperCommand.FILE:
            reject(
              new Error(
                `This course imports "${param}". Importing local files is not supported in the browser yet.`,
              ),
            )
            break
          default:
            console.warn('unknown command:', cmd, param)
        }
      })

      app.ports.output.subscribe(async (event) => {
        const [ok, json] = event

        if (!ok) {
          reject(new Error(String(json)))
          return
        }

        try {
          resolve(await this.dispatch(argument, json, fs))
        } catch (err) {
          reject(err)
        }
      })

      // The port protocol is `[format, inlineMarkdown]` — Worker.elm tries to
      // parse the second element as a URL first and falls through to loading it
      // as content, which is how inline markdown reaches the parser.
      app.ports.input.send([this.internalFormat(argument.format), markdown])
    })
  }

  /**
   * Routes Elm output to the matching exporter and collects its bytes.
   */
  private async dispatch(
    argument: Arguments,
    json: string,
    fs: MemoryFS,
  ): Promise<Uint8Array> {
    switch (argument.format) {
      case ExportFormat.JSON:
      case ExportFormat.FULL_JSON:
        return new TextEncoder().encode(json)

      case WEB.format:
        await WEB.exporter(argument, JSON.parse(json))
        // `web-zip` is forced on by the caller, so the exporter has written the
        // archive into the store rather than a directory tree.
        return fs.readFileRaw(argument.output + '.zip')

      default:
        throw new Error(`"${argument.format}" is not available in the browser`)
    }
  }

  /**
   * Mirrors `Exporter.determineInternalFormat` for the wired-up formats:
   * everything but plain json asks Elm for `fulljson` as its intermediate.
   */
  private internalFormat(format: string): string {
    return format === WEB.format ? ExportFormat.FULL_JSON : format
  }
}
