'use strict'

import { MemoryFS } from '../fs/memory'
import { Arguments } from '../parser'
import { useLocalContexts } from '../export/rdf'
import { AssetLoader } from './assets'
import { BrowserExporter } from './exporter'

import schemaOrg from './contexts/schema.org.json'

// Serve the schema.org context from the bundle: the network fetch jsonld would
// otherwise make is blocked by CORS in a browser, and would break offline use.
useLocalContexts({ 'http://schema.org': schemaOrg, 'https://schema.org': schemaOrg })

/** A course as the user supplied it, plus where its files live in the store. */
interface Course {
  /** The markdown source. */
  markdown: string
  /** Name shown in the UI and used for the downloaded file. */
  name: string
}

/**
 * Exports a course entirely in the browser and returns the finished bytes.
 *
 * The CLI reaches the same exporters through `validateAndNormalize`, which
 * fills in `path`, `readme` and `fs`. There is no argv here, so this builds the
 * equivalent `Arguments` directly — the defaults below mirror that function.
 */
export async function exportCourse(
  course: Course,
  format: string,
  onProgress?: (message: string) => void,
): Promise<{ bytes: Uint8Array; filename: string }> {
  const fs = new MemoryFS()
  const assets = new AssetLoader(fs)

  onProgress?.('Loading assets…')
  await assets.ensure(format, (bundle, index, total) =>
    onProgress?.(`Loading assets (${index + 1}/${total}): ${bundle}…`),
  )

  // The course itself has to be in the store too: `web.ts` copies
  // `argument.path` wholesale into the temp dir to pick up local images and
  // the readme it later rewrites.
  const root = '/course'
  const readme = 'README.md'
  await fs.writeFile(`${root}/${readme}`, course.markdown)

  const argument = {
    input: `${root}/${readme}`,
    readme: `./${readme}`,
    path: root,
    output: '/out/' + course.name,
    format,
    fs,

    // Forced on so the exporter writes one archive into the store instead of a
    // directory tree — bytes are what a download needs. See `web.finalizeOutput`.
    'web-zip': true,
  } as Arguments

  onProgress?.('Exporting…')
  const bytes = await new BrowserExporter().run(argument, course.markdown)

  return { bytes, filename: filenameFor(course.name, format) }
}

/** Extension the produced bytes actually carry, per format. */
function filenameFor(name: string, format: string): string {
  switch (format) {
    case 'json':
    case 'fulljson':
      return `${name}.json`
    default:
      return `${name}.zip`
  }
}

/** Hands the finished bytes to the browser as a file download. */
export function download(bytes: Uint8Array, filename: string): void {
  // Copy into a fresh buffer: the view may be backed by a larger pooled
  // ArrayBuffer, which Blob would otherwise include in full.
  const blob = new Blob([bytes.slice()], { type: 'application/octet-stream' })
  const url = URL.createObjectURL(blob)

  const link = document.createElement('a')
  link.href = url
  link.download = filename
  link.click()

  URL.revokeObjectURL(url)
}
