'use strict'

import { exportCourse, download } from './index'

/**
 * Development harness for the static app.
 *
 * Deliberately minimal: it exists to exercise the browser export path
 * end-to-end. The shipping UI is meant to start as a fork of
 * `src/server/public/`, which already has the format pickers, presets and i18n.
 */
const markdown = document.getElementById('markdown') as HTMLTextAreaElement
const format = document.getElementById('format') as HTMLSelectElement
const button = document.getElementById('export') as HTMLButtonElement
const status = document.getElementById('status') as HTMLSpanElement

function report(message: string, isError = false): void {
  status.textContent = message
  status.classList.toggle('error', isError)
}

button.addEventListener('click', async () => {
  button.disabled = true
  report('')

  const started = performance.now()

  try {
    const { bytes, filename } = await exportCourse(
      { markdown: markdown.value, name: 'course' },
      format.value,
      report,
    )

    download(bytes, filename)

    const seconds = ((performance.now() - started) / 1000).toFixed(1)
    report(`${filename} — ${(bytes.length / 1024 / 1024).toFixed(1)} MB, ${seconds}s`)
  } catch (error) {
    console.error(error)
    report(error instanceof Error ? error.message : String(error), true)
  } finally {
    button.disabled = false
  }
})
