'use strict'

import { unzipSync } from 'fflate'
import { MemoryFS } from '../fs/memory'

// Bundled through Parcel rather than fetched from a path built at runtime, so
// the archives are emitted as real assets with hashed, cache-busting URLs and
// resolve identically under `parcel serve` and `parcel build`. A hand-built URL
// is not served by the dev server at all: it answers unknown paths with the
// HTML fallback, which surfaces much later as "invalid zip data".
// The `url:` scheme is Parcel's, and is used instead of `import.meta.url`
// because this repo's tsconfig targets CommonJS for the CLI build.
// @ts-expect-error - Parcel resolves `url:` imports to the emitted asset URL
import webBundle from 'url:./static/assets/web.zip'
// @ts-expect-error - see above
import commonBundle from 'url:./static/assets/common.zip'

const BUNDLES: Record<string, string> = {
  web: webBundle,
  common: commonBundle,
}

/**
 * Asset bundles each format needs seeded before it can run.
 *
 * These mirror the `assets/<name>` directories the ported exporters read via
 * `fs.assetRoot()` — see `web.ts:copyAssets`. Every format pairs its own bundle
 * with the shared `common` one, which is what `asset:deduplicate` factored out.
 */
const REQUIRED: Record<string, string[]> = {
  json: [],
  fulljson: [],
  web: ['web', 'common'],
}

/**
 * Fetches and seeds the asset bundles a format needs, once per session.
 *
 * Assets are shipped as one zip per bundle rather than loose files: `web` alone
 * is 612 files, and fetching those individually would spend the whole budget on
 * request overhead. Bundles already seeded are skipped, so switching formats
 * only pays for what is new.
 */
export class AssetLoader {
  private loaded = new Set<string>()

  constructor(private fs: MemoryFS) {}

  /** Bundles needed by `format` that have not been seeded yet. */
  missing(format: string): string[] {
    const required = REQUIRED[format]

    if (!required) {
      throw new Error(`unknown format "${format}"`)
    }

    return required.filter((bundle) => !this.loaded.has(bundle))
  }

  /**
   * Ensures every bundle `format` needs is in the store.
   * `onProgress` reports each bundle as it starts, for a UI that would
   * otherwise sit silent through a 21MB download.
   */
  async ensure(
    format: string,
    onProgress?: (bundle: string, index: number, total: number) => void,
  ): Promise<void> {
    const missing = this.missing(format)

    for (const [index, bundle] of missing.entries()) {
      onProgress?.(bundle, index, missing.length)
      await this.seedBundle(bundle)
    }
  }

  private async seedBundle(bundle: string): Promise<void> {
    const url = BUNDLES[bundle]
    const response = await fetch(url)

    if (!response.ok) {
      throw new Error(
        `could not load the "${bundle}" assets (${response.status} from ${url})`,
      )
    }

    const archive = new Uint8Array(await response.arrayBuffer())
    const entries = unzipSync(archive)

    // Zip entries are relative to the bundle root, and `seed` places them below
    // `assetRoot()`. That root is the directory *containing* `assets` — it is
    // `dist/` under Node — and the exporters ask for `./assets/<bundle>/...`,
    // so the `assets/` segment has to be part of the key.
    const seed: Record<string, Uint8Array> = {}

    for (const [name, bytes] of Object.entries(entries)) {
      // Directory entries have a trailing slash and no content.
      if (name.endsWith('/')) continue

      seed[`assets/${bundle}/${name}`] = bytes
    }

    this.fs.seed(seed)
    this.loaded.add(bundle)
  }
}
